<?php
class LocationController extends Controller{private function model(){require_once __DIR__.'/../models/Location.php';return new Location();}public function index(){require_role(['Admin','Staff']);$locations=$this->model()->all();$this->view('locations/index',compact('locations'));}public function create(){require_role(['Admin']);$this->view('locations/form',['location'=>null,'action'=>url('locations/store')]);}public function store(){verify_csrf();require_role(['Admin']);$this->model()->create(['district'=>$_POST['district'],'city'=>$_POST['city'],'postcode'=>$_POST['postcode'],'transport_zone'=>$_POST['transport_zone'],'is_popular'=>isset($_POST['is_popular'])?1:0]);Session::flash('success','Location created.');$this->redirect('locations');}public function edit(){require_role(['Admin']);$location=$this->model()->find($_GET['id']);$this->view('locations/form',['location'=>$location,'action'=>url('locations/update?id='.$_GET['id'])]);}public function update(){verify_csrf();require_role(['Admin']);$this->model()->update($_GET['id'],['district'=>$_POST['district'],'city'=>$_POST['city'],'postcode'=>$_POST['postcode'],'transport_zone'=>$_POST['transport_zone'],'is_popular'=>isset($_POST['is_popular'])?1:0]);Session::flash('success','Location updated.');$this->redirect('locations');}public function delete(){require_role(['Admin']);$this->model()->delete($_GET['id']);Session::flash('success','Location deleted.');$this->redirect('locations');}}
